function getDicewareWord(diceCode) {
  return EFF_LARGE_WORDLIST[diceCode] || 'passvault';
}

function generateRandomPassphrase(wordCount = 4, delimiter = '-') {
  const keys = Object.keys(EFF_LARGE_WORDLIST);
  const selected = [];
  for (let i = 0; i < wordCount; i++) {
    const randKey = keys[Math.floor(Math.random() * keys.length)];
    selected.push(EFF_LARGE_WORDLIST[randKey]);
  }
  return selected.join(delimiter);
}

module.exports = {
  EFF_LARGE_WORDLIST,
  getDicewareWord,
  generateRandomPassphrase
};
